def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Remove spaces from the input string
    clusters = []  # Initialize an empty list to store the extracted clusters
    stack = []  # Stack to track opening and closing parentheses

    start = 0
    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                start = stack.pop()
                clusters.append(paren_string[start:i+1])

    return clusters
